import Item from './masonry-item.svelte';
import Root from './masonry.svelte';

export { type MasonryChildProps, type MasonryProps, type MasonryRootProps } from './masonry.svelte';
export { type MasonryItemChildProps, type MasonryItemProps } from './masonry-item.svelte';

// The scroll / resize / throttle helpers stay out of the barrel on purpose: they are DOM plumbing,
// not reusable layout primitives (research R-10).
export {
	getMasonryContext,
	hasMasonryContext,
	MasonryState,
	setMasonryContext,
	type MasonryStateProps
} from './masonry.svelte.js';

export {
	createPositioner,
	resolveColumnCount,
	resolveColumnWidth,
	type Positioner,
	type PositionerItem,
	type PositionerOptions
} from './masonry-positioner.js';

export { createIntervalTree, type IntervalTree } from './masonry-interval-tree.js';

export {
	Root,
	Item,
	//
	Root as Masonry,
	Item as MasonryItem
};

import { getContext, hasContext, setContext } from 'svelte';

import type { Direction } from '$lib/components/ui/direction-provider/direction-provider.svelte.js';

import { createPositioner, type Positioner, type PositionerItem } from './masonry-positioner.js';

/** Upstream `DEBOUNCE_DELAY` — how long window resizes are coalesced for, in ms. */
const DEBOUNCE_DELAY = 300;

/** Upstream `SCROLL_FPS` — the default upper bound on scroll-driven recomputation. */
const SCROLL_FPS = 12;

type RafScheduled<T extends unknown[]> = {
	(...args: T): void;
	cancel: () => void;
};

/**
 * Coalesce repeated calls into a single `requestAnimationFrame`, replacing upstream's
 * `onRafSchedule` (lines 913–936).
 *
 * **Divergence.** Upstream guards with `if (frameId)`, so the very first call — when `frameId` is
 * still `null` — schedules nothing at all and the callback never runs until a second call lands.
 * The guard here is `if (frameId === null)`, which is the evident intent: schedule when no frame is
 * pending, and let a pending frame absorb later calls (with the latest arguments winning).
 */
function createRafSchedule<T extends unknown[]>(callback: (...args: T) => void): RafScheduled<T> {
	let lastArgs: T | undefined;
	let frameId: number | null = null;

	const scheduled = (...args: T) => {
		lastArgs = args;
		if (frameId !== null) return;

		frameId = requestAnimationFrame(() => {
			frameId = null;
			if (lastArgs) callback(...lastArgs);
		});
	};

	scheduled.cancel = () => {
		if (frameId === null) return;
		cancelAnimationFrame(frameId);
		frameId = null;
	};

	return scheduled;
}

type Throttled<T> = {
	(value: T): void;
	cancel: () => void;
};

/**
 * Rate-limit a value stream to `fps` updates per second, replacing upstream's `useThrottle`
 * (lines 1085–1149) including its leading-edge call and its trailing coalescing timeout.
 */
function createThrottle<T>(
	onValue: (value: T) => void,
	fps: number,
	leading: boolean
): Throttled<T> {
	const ms = 1000 / fps;
	let previous = 0;
	let trailing: ReturnType<typeof setTimeout> | null = null;

	function clearTrailing() {
		if (trailing === null) return;
		clearTimeout(trailing);
		trailing = null;
	}

	const throttled = (value: T) => {
		const now = typeof performance !== 'undefined' ? performance.now() : Date.now();

		function call() {
			previous = now;
			clearTrailing();
			onValue(value);
		}

		if (leading && previous === 0) {
			call();
			return;
		}

		if (now - previous > ms) {
			if (previous > 0) {
				call();
				return;
			}
			previous = now;
		}

		clearTrailing();
		trailing = setTimeout(() => {
			call();
			previous = 0;
		}, ms);
	};

	throttled.cancel = () => {
		previous = 0;
		clearTrailing();
	};

	return throttled;
}

/**
 * Track the debounced document size, replacing upstream's `useDebouncedWindowSize` (lines 847–906).
 * Returns the teardown. Not exported through `index.ts` — it is DOM plumbing, not a layout
 * primitive (research R-10).
 */
export function observeWindowSize(
	state: MasonryState,
	delayMs: number = DEBOUNCE_DELAY
): () => void {
	if (typeof window === 'undefined') return () => {};

	let timeout: ReturnType<typeof setTimeout> | null = null;

	function onResize() {
		if (timeout !== null) clearTimeout(timeout);
		timeout = setTimeout(() => {
			state.windowSize = state.readDocumentSize();
		}, delayMs);
	}

	window.addEventListener('resize', onResize, { passive: true });
	window.addEventListener('orientationchange', onResize);
	window.visualViewport?.addEventListener('resize', onResize);

	return () => {
		window.removeEventListener('resize', onResize);
		window.removeEventListener('orientationchange', onResize);
		window.visualViewport?.removeEventListener('resize', onResize);
		if (timeout !== null) clearTimeout(timeout);
	};
}

/**
 * Track the throttled window scroll offset and the "is scrolling" flag, replacing upstream's
 * `useScroller` (lines 1020–1083). Returns the teardown.
 *
 * **Divergence.** Upstream settles `isScrolling` through a `requestAnimationFrame` polling loop that
 * compares timestamps; a single `setTimeout` of the same `40 + 1000 / fps` delay is equivalent and
 * does not keep a frame loop alive while the page is idle.
 */
export function observeWindowScroll(state: MasonryState, fps: number = SCROLL_FPS): () => void {
	if (typeof window === 'undefined') return () => {};

	const settleDelay = 40 + 1000 / fps;
	let settle: ReturnType<typeof setTimeout> | null = null;

	const throttled = createThrottle<number>(
		(scrollY) => {
			state.scrollY = scrollY;
		},
		fps,
		true
	);

	function onScroll() {
		state.isScrolling = true;
		if (settle !== null) clearTimeout(settle);
		settle = setTimeout(() => {
			state.isScrolling = false;
		}, settleDelay);

		throttled(window.scrollY ?? document.documentElement.scrollTop ?? 0);
	}

	window.addEventListener('scroll', onScroll, { passive: true });

	return () => {
		window.removeEventListener('scroll', onScroll);
		throttled.cancel();
		if (settle !== null) clearTimeout(settle);
	};
}

/**
 * Every positioned item overlapping `[low, high]`, by index.
 *
 * Built here rather than inside the class because the result is only ever *replaced*, never mutated
 * — the `ReadonlyMap` return type says so, and keeping the construction outside the reactive class
 * keeps that promise checkable (the same reasoning as `badge-overflow`'s width map).
 */
function collectVisible(
	positioner: Positioner,
	low: number,
	high: number
): ReadonlyMap<number, PositionerItem> {
	const entries: [number, PositionerItem][] = [];
	positioner.range(low, high, (index) => {
		const item = positioner.get(index);
		if (item) entries.push([index, item]);
	});
	return new Map(entries);
}

export type MasonryStateProps = {
	readonly getColumnWidth: () => number;
	readonly getColumnCount: () => number | undefined;
	readonly getMaxColumnCount: () => number | undefined;
	readonly getGap: () => number | { column: number; row: number };
	readonly getItemHeight: () => number;
	readonly getDefaultWidth: () => number | undefined;
	readonly getDefaultHeight: () => number | undefined;
	readonly getOverscan: () => number;
	readonly getScrollFps: () => number;
	readonly getLinear: () => boolean;
	readonly getDir: () => Direction;
};

/**
 * One instance per `<Masonry.Root>`, published on context.
 *
 * It replaces upstream's whole React shell — `usePositioner`, `useResizeObserver`, `useScroller`,
 * `useDebouncedWindowSize` and `MasonryContextValue` — and, because Svelte cannot inspect a
 * `Snippet` the way `React.Children.toArray` inspects children (research R-01), it also owns the
 * item registry that upstream derived from child position.
 */
export class MasonryState {
	// $derived below is lazy at runtime (evaluated only when a member is read), but svelte-check's
	// static analysis cannot see that and flags the field as used before its constructor assignment.
	#props!: MasonryStateProps;

	/** The root element, published by `<Masonry.Root>`. Stays `null` in `child` mode. */
	rootElement: HTMLElement | null = $state(null);
	/** `false` until the root's `$effect.pre` runs — i.e. on the server and on the first client pass. */
	mounted: boolean = $state(false);
	/** The debounced document size; seeded from `defaultWidth`/`defaultHeight` when there is no DOM. */
	windowSize: { width: number; height: number } = $state.raw({ width: 0, height: 0 });
	/** The root's offsetTop chain sum and its measured width (upstream lines 1243–1263). */
	containerPosition: { offset: number; width: number } = $state.raw({ offset: 0, width: 0 });
	/** The throttled `window.scrollY`. */
	scrollY: number = $state(0);
	/** True between a scroll tick and its `40 + 1000 / fps` ms settle. */
	isScrolling: boolean = $state(false);
	/** RAF-driven invalidation token; surfaced as `data-version` on the viewport. */
	layoutVersion: number = $state(0);

	/** Registration order of the live items (research R-02). */
	#tokens: symbol[] = $state.raw([]);
	/** Bumped whenever an item leaves, forcing a from-scratch re-measure of the shifted indices. */
	#structureVersion: number = $state(0);

	/**
	 * Every measured height, in index order — the single source of truth a recreated positioner
	 * replays from. Deliberately plain: it is written while the positioner is being mutated, and
	 * making it reactive would make the positioner derivation depend on its own side effects.
	 */
	#heights: number[] = [];
	/**
	 * Heights reported out of order, sparse by index, awaiting the predecessors that unblock them.
	 * A sparse array rather than a `Map` because it is mutated in place and must stay non-reactive.
	 */
	#pendingHeights: (number | undefined)[] = [];
	#elementIndex = new WeakMap<Element, number>();
	#updates: number[] = [];
	#observer: ResizeObserver | null = null;
	#lastOffset = -1;
	#lastWidth = -1;

	readonly columnGap: number = $derived.by(() => {
		const gap = this.#props.getGap();
		return typeof gap === 'object' ? gap.column : gap;
	});

	readonly rowGap: number = $derived.by(() => {
		const gap = this.#props.getGap();
		return typeof gap === 'object' ? gap.row : gap;
	});

	readonly dir: Direction = $derived(this.#props.getDir());

	/** The width the layout is computed against: the measured container, else the document. */
	readonly width: number = $derived(this.containerPosition.width || this.windowSize.width);

	/**
	 * Recreated whenever any of the seven layout inputs changes, replaying every height measured so
	 * far into the new instance — upstream lines 817–835.
	 *
	 * The derivation is **pure and idempotent**: it writes no state and carries nothing between
	 * runs, so evaluating it twice yields the same layout. That matters because the measurement
	 * effects mutate the instance it returns; a derivation that remembered its previous instance
	 * could hand out a positioner whose heights had been recorded into a discarded one.
	 */
	readonly positioner: Positioner = $derived.by(() => {
		// A structural change (an item leaving) shifts every later index, so `#heights` has already
		// been emptied — reading the version is what makes this derivation re-run for it.
		void this.#structureVersion;

		const next = createPositioner({
			width: this.width,
			columnWidth: this.#props.getColumnWidth(),
			columnGap: this.columnGap,
			rowGap: this.rowGap,
			columnCount: this.#props.getColumnCount(),
			maxColumnCount: this.#props.getMaxColumnCount(),
			linear: this.#props.getLinear()
		});

		for (let index = 0; index < this.#heights.length; index++) {
			next.set(index, this.#heights[index]);
		}

		return next;
	});

	readonly columnWidth: number = $derived(this.positioner.columnWidth);
	readonly columnCount: number = $derived(this.positioner.columnCount);
	readonly itemCount: number = $derived(this.#tokens.length);

	readonly measuredCount: number = $derived.by(() => {
		void this.layoutVersion;
		return this.positioner.size();
	});

	readonly shortestColumnSize: number = $derived.by(() => {
		void this.layoutVersion;
		return this.positioner.shortestColumn();
	});

	readonly scrollTop: number = $derived(Math.max(0, this.scrollY - this.containerPosition.offset));
	readonly overscanPixels: number = $derived(this.windowSize.height * this.#props.getOverscan());
	readonly rangeStart: number = $derived(Math.max(0, this.scrollTop - this.overscanPixels / 2));
	readonly rangeEnd: number = $derived(this.scrollTop + this.overscanPixels);

	readonly layoutOutdated: boolean = $derived(
		this.shortestColumnSize < this.rangeEnd && this.measuredCount < this.itemCount
	);

	/** How many unmeasured items the next hidden measurement pass covers (upstream 1431–1438). */
	readonly batchSize: number = $derived(
		Math.min(
			this.itemCount - this.measuredCount,
			Math.ceil(
				((this.scrollTop + this.overscanPixels - this.shortestColumnSize) /
					this.#props.getItemHeight()) *
					this.columnCount
			)
		)
	);

	/** Every positioned item whose extent overlaps the overscan window, by index. */
	readonly visibleIndices: ReadonlyMap<number, PositionerItem> = $derived.by(() => {
		void this.layoutVersion;
		return collectVisible(this.positioner, this.rangeStart, this.rangeEnd);
	});

	/** The viewport's height, extrapolating the not-yet-measured items (upstream 1479–1492). */
	readonly estimatedHeight: number = $derived.by(() => {
		const measuredHeight = this.positioner.estimateHeight(
			this.measuredCount,
			this.#props.getItemHeight()
		);
		if (this.measuredCount === this.itemCount) return measuredHeight;

		const remaining = this.itemCount - this.measuredCount;
		return measuredHeight + Math.ceil((remaining / this.columnCount) * this.#props.getItemHeight());
	});

	#bump = createRafSchedule(() => {
		this.layoutVersion += 1;
	});

	#flushUpdates = createRafSchedule(() => {
		if (this.#updates.length === 0) return;

		this.positioner.update(this.#updates);
		// Keep the replay log in step, or a later positioner recreation would resurrect the height
		// this update just replaced.
		for (let cursor = 0; cursor < this.#updates.length - 1; cursor += 2) {
			this.#heights[this.#updates[cursor]] = this.#updates[cursor + 1];
		}

		this.#updates = [];
		this.layoutVersion += 1;
	});

	constructor(props: MasonryStateProps) {
		this.#props = props;
		this.windowSize = this.readDocumentSize();
	}

	/** The document size, or the declared defaults when there is no DOM (server render). */
	readDocumentSize(): { width: number; height: number } {
		if (typeof document === 'undefined') {
			return {
				width: this.#props.getDefaultWidth() ?? 0,
				height: this.#props.getDefaultHeight() ?? 0
			};
		}

		const element = this.rootElement;
		return {
			width: element ? element.offsetWidth : document.documentElement.clientWidth,
			height: document.documentElement.clientHeight
		};
	}

	/**
	 * Measure the root's offset from the top of the document and its width. Compared against plain
	 * mirrors rather than the reactive value, so the caller's effect never reads what it writes.
	 */
	measureContainer(element: HTMLElement | null): void {
		if (!element) return;

		let offset = 0;
		let current: HTMLElement | null = element;
		do {
			offset += current.offsetTop ?? 0;
			current = current.offsetParent as HTMLElement | null;
		} while (current);

		const width = element.offsetWidth;
		if (offset === this.#lastOffset && width === this.#lastWidth) return;

		this.#lastOffset = offset;
		this.#lastWidth = width;
		this.containerPosition = { offset, width };
	}

	registerItem(token: symbol): void {
		this.#tokens = [...this.#tokens, token];
	}

	unregisterItem(token: symbol): void {
		const position = this.#tokens.indexOf(token);
		if (position === -1) return;

		this.#tokens = this.#tokens.filter((candidate) => candidate !== token);
		// Every index after `position` shifts, so nothing measured can be trusted any more. Bumping
		// the version last means every effect it wakes sees the cleared buffers.
		this.#heights = [];
		this.#pendingHeights = [];
		this.#updates = [];
		this.#structureVersion += 1;
	}

	indexOf(token: symbol): number {
		return this.#tokens.indexOf(token);
	}

	/**
	 * The item's current geometry, as a fresh object.
	 *
	 * `positioner.update()` re-flows a column by mutating the stored items **in place**, so handing
	 * the stored object straight back would let a `$derived` compare it `===` to its previous value
	 * and skip the update — the re-flow would be computed and never rendered. Copying makes the
	 * `layoutVersion` invalidation observable.
	 */
	getItem(index: number): PositionerItem | undefined {
		void this.layoutVersion;
		const item = this.positioner.get(index);
		return item ? { ...item } : undefined;
	}

	isVisible(index: number): boolean {
		return this.visibleIndices.has(index);
	}

	/** True while the item belongs to the hidden batch rendered purely to be measured. */
	isMeasuring(index: number): boolean {
		if (!this.mounted || !this.layoutOutdated) return false;
		const start = this.measuredCount;
		return index >= start && index < start + this.batchSize;
	}

	/**
	 * Wire one item element up for measurement: remember its index, observe it, and report its
	 * current height. Returns the teardown the item's `$effect` must run.
	 */
	observeItem(index: number, element: HTMLElement): () => void {
		// Subscribes the caller's effect to structural changes, so every live item re-reports its
		// height after a removal shifted the indices and emptied the measurement log.
		void this.#structureVersion;

		this.#elementIndex.set(element, index);
		const observer = this.#ensureObserver();
		observer?.observe(element);
		this.reportHeight(index, element.offsetHeight);

		return () => {
			observer?.unobserve(element);
			this.#elementIndex.delete(element);
		};
	}

	/**
	 * Buffer a measured height and drain the buffer strictly in index order (research R-04).
	 *
	 * `positioner.set` appends to whichever column is currently shortest, so the assignment depends
	 * on call order. Holding an early report until its predecessors land is what makes the column
	 * choice identical to upstream's for the same height sequence (SC-001).
	 */
	reportHeight(index: number, height: number): void {
		if (index < 0 || index < this.#heights.length) return;

		// Captured once: a positioner recreated later replays `#heights`, so a stale instance here
		// can only ever lose work that the replay puts straight back.
		const positioner = this.positioner;
		this.#pendingHeights[index] = height;

		let drained = false;
		while (this.#pendingHeights[this.#heights.length] !== undefined) {
			const next = this.#heights.length;
			const measured = this.#pendingHeights[next] ?? 0;
			positioner.set(next, measured);
			this.#heights.push(measured);
			this.#pendingHeights[next] = undefined;
			drained = true;
		}

		if (drained) this.bumpLayout();
	}

	/** RAF-coalesced invalidation of everything derived from the positioner's mutable state. */
	bumpLayout(): void {
		this.#bump();
	}

	/** Drop every observer and pending frame. Called from the root's `$effect` teardown. */
	destroy(): void {
		this.#bump.cancel();
		this.#flushUpdates.cancel();
		this.#observer?.disconnect();
		this.#observer = null;
		this.#pendingHeights = [];
		this.#updates = [];
	}

	#ensureObserver(): ResizeObserver | null {
		if (typeof ResizeObserver === 'undefined') return null;
		if (this.#observer) return this.#observer;

		this.#observer = new ResizeObserver((entries) => {
			for (const entry of entries) {
				const target = entry.target;
				if (!(target instanceof HTMLElement)) continue;

				const index = this.#elementIndex.get(target);
				if (index === undefined) continue;

				const height = target.offsetHeight;
				if (height <= 0) continue;

				const item = this.positioner.get(index);
				if (item === undefined || height === item.height) continue;

				this.#updates.push(index, height);
			}

			this.#flushUpdates();
		});

		return this.#observer;
	}
}

const MASONRY_CONTEXT_KEY = Symbol('masonry');

export function setMasonryContext(state: MasonryState): MasonryState {
	return setContext(MASONRY_CONTEXT_KEY, state);
}

export function hasMasonryContext(): boolean {
	return hasContext(MASONRY_CONTEXT_KEY);
}

/** Read the root's state, throwing when there is no `<Masonry.Root>` ancestor. */
export function getMasonryContext(): MasonryState {
	if (!hasMasonryContext()) {
		throw new Error('`<Masonry.Item>` must be used within `<Masonry.Root>`.');
	}
	return getContext<MasonryState>(MASONRY_CONTEXT_KEY);
}

import { createIntervalTree } from './masonry-interval-tree.js';

/**
 * The column positioner — a pure port of upstream's `usePositioner` core (`masonry.tsx` lines
 * 548–799) with the `useRef`/`useCallback` shell stripped (research R-05).
 *
 * It owns the whole layout algorithm: how many columns fit, how wide they are, which column each
 * item lands in, and where later items move when one of them is re-measured. Nothing here is
 * reactive and nothing here reads the DOM, so upstream parity (SC-001) is directly unit-testable.
 */

const COLUMN_WIDTH = 200;
const GAP = 0;

export interface PositionerItem {
	/** Distance from the top of the viewport container, in px. */
	top: number;
	/**
	 * Offset from the *leading* inline edge, in px — direction-agnostic. The item renders it as
	 * `inset-inline-start`, so RTL mirroring is a CSS consequence and the numbers never change
	 * (research R-07).
	 */
	left: number;
	/** Last measured height, in px. */
	height: number;
	/** Which column this item was assigned to, 0-based from the leading edge. */
	columnIndex: number;
}

export interface PositionerOptions {
	/** Measured container width, in px. */
	width: number;
	/** @default 200 */
	columnWidth?: number;
	/** @default 0 */
	columnGap?: number;
	/** Falls back to `columnGap` when omitted. */
	rowGap?: number;
	/** Explicit column count; overrides the computed one. */
	columnCount?: number;
	/** Caps the computed column count. Ignored when `columnCount` is set. */
	maxColumnCount?: number;
	/** @default false */
	linear?: boolean;
}

export interface Positioner {
	/** How many columns this instance lays out into. */
	readonly columnCount: number;
	/** The width of one column, in px. */
	readonly columnWidth: number;
	/**
	 * Position the item at `index`, appending it to the chosen column.
	 *
	 * Callers must only ever pass `index === size()` — the assignment depends on call order, and
	 * that invariant is what keeps column choice identical to upstream (research R-04).
	 */
	set(index: number, height?: number): void;
	get(index: number): PositionerItem | undefined;
	/** Apply a flat `[index, height, index, height, …]` list and re-flow the affected columns. */
	update(updates: number[]): void;
	/** Report every positioned item whose vertical extent overlaps `[low, high]`. */
	range(
		low: number,
		high: number,
		onItemRender: (index: number, left: number, top: number) => void
	): void;
	/** How many items have been positioned. */
	size(): number;
	/** Total height for `itemCount` items, extrapolating the unmeasured ones. */
	estimateHeight(itemCount: number, defaultItemHeight: number): number;
	/** The height of the currently shortest column. */
	shortestColumn(): number;
	/** Every positioned item, in index order. */
	all(): PositionerItem[];
}

/**
 * `columnCount || min(floor((width + columnGap) / (columnWidth + columnGap)), maxColumnCount) || 1`
 * — upstream lines 610–616 verbatim. The trailing `|| 1` is what makes a container narrower than one
 * column still render exactly one column, because `floor(...)` is `0` there.
 */
export function resolveColumnCount(options: PositionerOptions): number {
	const {
		width,
		columnWidth = COLUMN_WIDTH,
		columnGap = GAP,
		columnCount,
		maxColumnCount
	} = options;

	return (
		columnCount ||
		Math.min(
			Math.floor((width + columnGap) / (columnWidth + columnGap)),
			maxColumnCount || Number.POSITIVE_INFINITY
		) ||
		1
	);
}

/** `floor((width - columnGap * (columnCount - 1)) / columnCount)` — upstream lines 617–619. */
export function resolveColumnWidth(options: PositionerOptions): number {
	const { width, columnGap = GAP } = options;
	const columnCount = resolveColumnCount(options);

	return Math.floor((width - columnGap * (columnCount - 1)) / columnCount);
}

/** Index of `target` in the ascending list `values`, or `-1`. */
function binarySearch(values: number[], target: number): number {
	let low = 0;
	let high = values.length - 1;

	while (low <= high) {
		const middle = (low + high) >>> 1;
		const value = values[middle];
		if (value === target) return middle;
		if (value <= target) low = middle + 1;
		else high = middle - 1;
	}

	return -1;
}

export function createPositioner(options: PositionerOptions): Positioner {
	const { columnGap = GAP, rowGap, linear = false } = options;

	const columnCount = resolveColumnCount(options);
	const columnWidth = resolveColumnWidth(options);
	const verticalGap = rowGap ?? columnGap;

	const intervalTree = createIntervalTree();
	const columnHeights: number[] = new Array<number>(columnCount).fill(0);
	const items: (PositionerItem | undefined)[] = [];
	const columnItems: number[][] = Array.from({ length: columnCount }, () => []);

	/** Index of the shortest column; ties resolve to the lowest index. */
	function shortestColumnIndex(): number {
		let shortest = 0;
		for (let index = 1; index < columnHeights.length; index++) {
			if (columnHeights[index] < columnHeights[shortest]) shortest = index;
		}
		return shortest;
	}

	/**
	 * Round-robin placement with upstream's escape hatch: keep the preferred column while its
	 * resulting height stays within `shortestHeight + height * 2.5`, otherwise drop to the
	 * shortest column so one runaway column cannot starve the rest.
	 */
	function linearColumnIndex(index: number, height: number): number {
		const preferredColumn = index % columnCount;
		const shortestIndex = shortestColumnIndex();
		const shortestHeight = columnHeights[shortestIndex];
		const preferredHeight = columnHeights[preferredColumn] + height;

		return preferredHeight <= shortestHeight + height * 2.5 ? preferredColumn : shortestIndex;
	}

	return {
		columnCount,
		columnWidth,

		set(index: number, height = 0) {
			const columnIndex = linear ? linearColumnIndex(index, height) : shortestColumnIndex();

			const top = columnHeights[columnIndex];
			columnHeights[columnIndex] = top + height + verticalGap;
			columnItems[columnIndex].push(index);

			items[index] = {
				left: columnIndex * (columnWidth + columnGap),
				top,
				height,
				columnIndex
			};
			intervalTree.insert(top, top + height, index);
		},

		get(index: number) {
			return items[index];
		},

		update(updates: number[]) {
			const columns: (number | undefined)[] = new Array<number | undefined>(columnCount);

			for (let cursor = 0; cursor < updates.length - 1; cursor++) {
				const currentIndex = updates[cursor];
				const nextHeight = updates[++cursor];

				const item = items[currentIndex];
				if (!item) continue;

				item.height = nextHeight;
				intervalTree.remove(currentIndex);
				intervalTree.insert(item.top, item.top + item.height, currentIndex);

				const known = columns[item.columnIndex];
				columns[item.columnIndex] =
					known === undefined ? currentIndex : Math.min(currentIndex, known);
			}

			for (let column = 0; column < columns.length; column++) {
				const firstChanged = columns[column];
				if (firstChanged === undefined) continue;

				const itemsInColumn = columnItems[column];
				const startIndex = binarySearch(itemsInColumn, firstChanged);
				if (startIndex === -1) continue;

				const startItem = items[itemsInColumn[startIndex]];
				if (!startItem) continue;

				columnHeights[column] = startItem.top + startItem.height + verticalGap;

				for (let cursor = startIndex + 1; cursor < itemsInColumn.length; cursor++) {
					const currentIndex = itemsInColumn[cursor];
					const item = items[currentIndex];
					if (!item) continue;

					item.top = columnHeights[column];
					columnHeights[column] = item.top + item.height + verticalGap;
					intervalTree.remove(currentIndex);
					intervalTree.insert(item.top, item.top + item.height, currentIndex);
				}
			}
		},

		range(low, high, onItemRender) {
			intervalTree.search(low, high, (index, top) => {
				const item = items[index];
				if (!item) return;
				onItemRender(index, item.left, top);
			});
		},

		size() {
			return intervalTree.size;
		},

		estimateHeight(itemCount, defaultItemHeight) {
			const tallestColumn = Math.max(0, Math.max(...columnHeights));

			return itemCount === intervalTree.size
				? tallestColumn
				: tallestColumn +
						Math.ceil((itemCount - intervalTree.size) / columnCount) * defaultItemHeight;
		},

		shortestColumn() {
			if (columnHeights.length > 1) return Math.min(...columnHeights);
			return columnHeights[0] ?? 0;
		},

		all() {
			return items.filter((item): item is PositionerItem => item !== undefined);
		}
	};
}

/**
 * A red-black interval tree — a direct, behaviour-preserving port of upstream's
 * `createIntervalTree` (`masonry.tsx` lines 8–426).
 *
 * It answers one question for the masonry positioner: *which item indices have a vertical extent
 * overlapping `[low, high]`?* Mutation is the point, so nothing here is reactive and nothing here
 * touches the DOM — which is what makes the layout parity assertions unit-testable without jsdom.
 */

const NODE_COLOR = {
	RED: 0,
	BLACK: 1,
	SENTINEL: 2
} as const;

const NODE_OPERATION = {
	REMOVE: 0,
	PRESERVE: 1
} as const;

type NodeColor = (typeof NODE_COLOR)[keyof typeof NODE_COLOR];
type NodeOperation = (typeof NODE_OPERATION)[keyof typeof NODE_OPERATION];

/** One index stored at a tree node, ordered by descending `high`. */
interface ListNode {
	index: number;
	high: number;
	next: ListNode | null;
}

interface TreeNode {
	max: number;
	low: number;
	high: number;
	color: NodeColor;
	parent: TreeNode;
	right: TreeNode;
	left: TreeNode;
	list: ListNode;
}

interface Tree {
	root: TreeNode;
	size: number;
}

/**
 * The shared leaf terminator. Upstream builds it with `undefined as unknown as TreeNode`; here it is
 * constructed explicitly and then closed over itself, so no assertion widens a real type away
 * (Constitution Principle VI). Its `list` is a never-read placeholder — every code path that reads
 * `node.list` has already excluded the sentinel.
 */
function createSentinel(): TreeNode {
	const sentinel: Partial<TreeNode> = {
		low: 0,
		max: 0,
		high: 0,
		color: NODE_COLOR.SENTINEL,
		list: { index: -1, high: 0, next: null }
	};

	const node = sentinel as TreeNode;
	node.parent = node;
	node.left = node;
	node.right = node;

	return node;
}

const SENTINEL_NODE = createSentinel();

/** Insert `index` into a node's descending-`high` list. Returns `false` when it is already there. */
function addInterval(treeNode: TreeNode, high: number, index: number): boolean {
	let node: ListNode | null = treeNode.list;
	let prevNode: ListNode | undefined;

	while (node) {
		if (node.index === index) return false;
		if (high > node.high) break;
		prevNode = node;
		node = node.next;
	}

	if (!prevNode) treeNode.list = { index, high, next: node };
	if (prevNode) prevNode.next = { index, high, next: prevNode.next };

	return true;
}

/**
 * Drop `index` from a node's list. Returns `REMOVE` when the node is now empty and must leave the
 * tree, `PRESERVE` when it still holds other indices, and `undefined` when `index` was not there.
 */
function removeInterval(treeNode: TreeNode, index: number): NodeOperation | undefined {
	let node: ListNode | null = treeNode.list;
	if (node.index === index) {
		if (node.next === null) return NODE_OPERATION.REMOVE;
		treeNode.list = node.next;
		return NODE_OPERATION.PRESERVE;
	}

	let prevNode: ListNode = node;
	node = node.next;

	while (node !== null) {
		if (node.index === index) {
			prevNode.next = node.next;
			return NODE_OPERATION.PRESERVE;
		}
		prevNode = node;
		node = node.next;
	}

	return undefined;
}

function updateMax(node: TreeNode) {
	const max = node.high;
	if (node.left === SENTINEL_NODE && node.right === SENTINEL_NODE) node.max = max;
	else if (node.left === SENTINEL_NODE) node.max = Math.max(node.right.max, max);
	else if (node.right === SENTINEL_NODE) node.max = Math.max(node.left.max, max);
	else node.max = Math.max(Math.max(node.left.max, node.right.max), max);
}

function updateMaxUp(node: TreeNode) {
	let current = node;

	while (current.parent !== SENTINEL_NODE) {
		updateMax(current.parent);
		current = current.parent;
	}
}

function rotateLeft(tree: Tree, x: TreeNode) {
	if (x.right === SENTINEL_NODE) return;
	const y = x.right;
	x.right = y.left;
	if (y.left !== SENTINEL_NODE) y.left.parent = x;
	y.parent = x.parent;

	if (x.parent === SENTINEL_NODE) tree.root = y;
	else if (x === x.parent.left) x.parent.left = y;
	else x.parent.right = y;

	y.left = x;
	x.parent = y;

	updateMax(x);
	updateMax(y);
}

function rotateRight(tree: Tree, x: TreeNode) {
	if (x.left === SENTINEL_NODE) return;
	const y = x.left;
	x.left = y.right;
	if (y.right !== SENTINEL_NODE) y.right.parent = x;
	y.parent = x.parent;

	if (x.parent === SENTINEL_NODE) tree.root = y;
	else if (x === x.parent.right) x.parent.right = y;
	else x.parent.left = y;

	y.right = x;
	x.parent = y;

	updateMax(x);
	updateMax(y);
}

function replaceNode(tree: Tree, x: TreeNode, y: TreeNode) {
	if (x.parent === SENTINEL_NODE) tree.root = y;
	else if (x === x.parent.left) x.parent.left = y;
	else x.parent.right = y;
	y.parent = x.parent;
}

function fixRemove(tree: Tree, node: TreeNode) {
	let x = node;
	let w: TreeNode;

	while (x !== SENTINEL_NODE && x.color === NODE_COLOR.BLACK) {
		if (x === x.parent.left) {
			w = x.parent.right;

			if (w.color === NODE_COLOR.RED) {
				w.color = NODE_COLOR.BLACK;
				x.parent.color = NODE_COLOR.RED;
				rotateLeft(tree, x.parent);
				w = x.parent.right;
			}

			if (w.left.color === NODE_COLOR.BLACK && w.right.color === NODE_COLOR.BLACK) {
				w.color = NODE_COLOR.RED;
				x = x.parent;
			} else {
				if (w.right.color === NODE_COLOR.BLACK) {
					w.left.color = NODE_COLOR.BLACK;
					w.color = NODE_COLOR.RED;
					rotateRight(tree, w);
					w = x.parent.right;
				}

				w.color = x.parent.color;
				x.parent.color = NODE_COLOR.BLACK;
				w.right.color = NODE_COLOR.BLACK;
				rotateLeft(tree, x.parent);
				x = tree.root;
			}
		} else {
			w = x.parent.left;

			if (w.color === NODE_COLOR.RED) {
				w.color = NODE_COLOR.BLACK;
				x.parent.color = NODE_COLOR.RED;
				rotateRight(tree, x.parent);
				w = x.parent.left;
			}

			if (w.right.color === NODE_COLOR.BLACK && w.left.color === NODE_COLOR.BLACK) {
				w.color = NODE_COLOR.RED;
				x = x.parent;
			} else {
				if (w.left.color === NODE_COLOR.BLACK) {
					w.right.color = NODE_COLOR.BLACK;
					w.color = NODE_COLOR.RED;
					rotateLeft(tree, w);
					w = x.parent.left;
				}

				w.color = x.parent.color;
				x.parent.color = NODE_COLOR.BLACK;
				w.left.color = NODE_COLOR.BLACK;
				rotateRight(tree, x.parent);
				x = tree.root;
			}
		}
	}

	x.color = NODE_COLOR.BLACK;
}

function minimumTree(node: TreeNode) {
	let current = node;
	while (current.left !== SENTINEL_NODE) {
		current = current.left;
	}
	return current;
}

function fixInsert(tree: Tree, node: TreeNode) {
	let current = node;
	let y: TreeNode;

	while (current.parent.color === NODE_COLOR.RED) {
		if (current.parent === current.parent.parent.left) {
			y = current.parent.parent.right;

			if (y.color === NODE_COLOR.RED) {
				current.parent.color = NODE_COLOR.BLACK;
				y.color = NODE_COLOR.BLACK;
				current.parent.parent.color = NODE_COLOR.RED;
				current = current.parent.parent;
			} else {
				if (current === current.parent.right) {
					current = current.parent;
					rotateLeft(tree, current);
				}

				current.parent.color = NODE_COLOR.BLACK;
				current.parent.parent.color = NODE_COLOR.RED;
				rotateRight(tree, current.parent.parent);
			}
		} else {
			y = current.parent.parent.left;

			if (y.color === NODE_COLOR.RED) {
				current.parent.color = NODE_COLOR.BLACK;
				y.color = NODE_COLOR.BLACK;
				current.parent.parent.color = NODE_COLOR.RED;
				current = current.parent.parent;
			} else {
				if (current === current.parent.left) {
					current = current.parent;
					rotateRight(tree, current);
				}

				current.parent.color = NODE_COLOR.BLACK;
				current.parent.parent.color = NODE_COLOR.RED;
				rotateLeft(tree, current.parent.parent);
			}
		}
	}
	tree.root.color = NODE_COLOR.BLACK;
}

export interface IntervalTree {
	/** Store `index` as covering `[low, high]`. A duplicate index at the same `low` is a no-op. */
	insert(low: number, high: number, index: number): void;
	/** Forget `index`. An index the tree never held is a no-op. */
	remove(index: number): void;
	/**
	 * Invoke `onCallback(index, low)` for every interval overlapping `[low, high]`, in
	 * tree-traversal order — **not** in index order. Callers must not assume ordering.
	 */
	search(low: number, high: number, onCallback: (index: number, low: number) => void): void;
	/** How many *intervals* are stored; several indices may share one `low`. */
	readonly size: number;
}

export function createIntervalTree(): IntervalTree {
	const tree: Tree = {
		root: SENTINEL_NODE,
		size: 0
	};

	const indexMap = new Map<number, TreeNode>();

	return {
		insert(low, high, index) {
			let x: TreeNode = tree.root;
			let y: TreeNode = SENTINEL_NODE;

			while (x !== SENTINEL_NODE) {
				y = x;
				if (low === y.low) break;
				if (low < x.low) x = x.left;
				else x = x.right;
			}

			if (low === y.low && y !== SENTINEL_NODE) {
				if (!addInterval(y, high, index)) return;
				y.high = Math.max(y.high, high);
				updateMax(y);
				updateMaxUp(y);
				indexMap.set(index, y);
				tree.size++;
				return;
			}

			const z: TreeNode = {
				low,
				high,
				max: high,
				color: NODE_COLOR.RED,
				parent: y,
				left: SENTINEL_NODE,
				right: SENTINEL_NODE,
				list: { index, high, next: null }
			};

			if (y === SENTINEL_NODE) {
				tree.root = z;
			} else {
				if (z.low < y.low) y.left = z;
				else y.right = z;
				updateMaxUp(z);
			}

			fixInsert(tree, z);
			indexMap.set(index, z);
			tree.size++;
		},

		remove(index) {
			const z = indexMap.get(index);
			if (z === undefined) return;
			indexMap.delete(index);

			const intervalResult = removeInterval(z, index);
			if (intervalResult === undefined) return;
			if (intervalResult === NODE_OPERATION.PRESERVE) {
				z.high = z.list.high;
				updateMax(z);
				updateMaxUp(z);
				tree.size--;
				return;
			}

			let y = z;
			let originalYColor = y.color;
			let x: TreeNode;

			if (z.left === SENTINEL_NODE) {
				x = z.right;
				replaceNode(tree, z, z.right);
			} else if (z.right === SENTINEL_NODE) {
				x = z.left;
				replaceNode(tree, z, z.left);
			} else {
				y = minimumTree(z.right);
				originalYColor = y.color;
				x = y.right;

				if (y.parent === z) {
					x.parent = y;
				} else {
					replaceNode(tree, y, y.right);
					y.right = z.right;
					y.right.parent = y;
				}

				replaceNode(tree, z, y);
				y.left = z.left;
				y.left.parent = y;
				y.color = z.color;
			}

			updateMax(x);
			updateMaxUp(x);

			if (originalYColor === NODE_COLOR.BLACK) fixRemove(tree, x);
			tree.size--;
		},

		search(low, high, onCallback) {
			const stack: TreeNode[] = [tree.root];
			while (stack.length !== 0) {
				const node = stack.pop();
				if (!node) continue;
				if (node === SENTINEL_NODE || low > node.max) continue;
				if (node.left !== SENTINEL_NODE) stack.push(node.left);
				if (node.right !== SENTINEL_NODE) stack.push(node.right);
				if (node.low <= high && node.high >= low) {
					let current: ListNode | null = node.list;
					while (current !== null) {
						if (current.high >= low) onCallback(current.index, node.low);
						current = current.next;
					}
				}
			}
		},

		get size() {
			return tree.size;
		}
	};
}
